#### JavaScript Interaction
```javascript
const sliderHandle = document.querySelector('.slider-handle');
const sliderCircle = document.querySelector('.slider-circle');
const radiusMarkers = document.querySelectorAll('.radius-marker');

let radius = 0;
let angle = 0;

sliderHandle.addEventListener('mousedown', (e) => {
  const rect = sliderHandle.getBoundingClientRect();
  const centerX = rect.left + rect.width / 2;
  const centerY = rect.top + rect.height / 2;

  const handleMouseMove = (e) => {
    const dx = e.clientX - centerX;
    const dy = e.clientY - centerY;
    const distance = Math.sqrt(dx * dx + dy * dy);

    radius = distance;
    angle = Math.atan2(dy, dx);

    updateSlider();
  };

  const handleMouseUp = () => {
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
  };

  document.addEventListener('mousemove', handleMouseMove);
  document.addEventListener('mouseup', handleMouseUp);
});

function updateSlider() {
  sliderCircle.setAttribute('r', radius);
  sliderCircle.setAttribute('stroke-dashoffset', 1256.64 - (2 * Math.PI * radius));

  sliderHandle.style.top = `${200 + radius * Math.sin(angle)}px`;
  sliderHandle.style.left = `${200 + radius * Math.cos(angle)}px`;

  radiusMarkers.forEach((marker) => {
    const markerRadius = parseInt(marker.getAttribute('r'));
    if (radius >= markerRadius) {
      marker.style.stroke = '#333';
    } else {
      marker.style.stroke = '#666';
    }
  });
}
```

