To demonstrate a blocking read interrupted by a signal with EINTR handling, we'll create a simple example using C programming language. In this example, we'll have a program that performs a blocking read on a file descriptor (in this case, standard input) and handles the case where the read is interrupted by a signal.

First, let's create a program that does a blocking read:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define BUFFER_SIZE 1024

// Signal handler function
void sigint_handler(int sig) {
    printf("Received signal %d\n", sig);
}

int main() {
    // Install signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    printf("Waiting for input...\n");

    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        bytes_read = read(STDIN_FILENO, buffer, BUFFER_SIZE - 1);

        if (bytes_read == -1) {
            if (errno == EINTR) {
                printf("Read interrupted by signal, retrying...\n");
                continue;
            } else {
                perror("read");
                exit(EXIT_FAILURE);
            }
        } else if (bytes_read == 0) {
            printf("End of input\n");
            break;
        }

        buffer[bytes_read] = '\0';
        printf("Read: %s\n", buffer);
    }

    return 0;
}
```

### Explanation:

1. **Signal Handling Setup**: The program sets up a signal handler for `SIGINT` (which is sent when the user presses Ctrl+C). The `sigint_handler` function simply prints a message when it's called.

2. **Blocking Read**: The program then enters a loop where it performs a blocking read on `STDIN_FILENO` (standard input).

3. **EINTR Handling**: If the read is interrupted by a signal, `read` will return `-1` and `errno` will be set to `EINTR`. The program checks for this condition and, if it occurs, prints a message and retries the read.

4. **Normal Read Completion**: If the read completes normally (not interrupted), the program prints out what was read.

### Testing:

- Compile the program with `gcc`: `gcc -o example example.c`
- Run the program: `./example`
- While the program is waiting for input, press Ctrl+C to send a `SIGINT` signal. The program should print "Received signal" and "Read interrupted by signal, retrying..." and then continue waiting for input.

This example demonstrates how to handle the case where a blocking read is interrupted by a signal, ensuring that your program can recover and continue executing as needed.

**Reading Network Packets from a Socket in C++**
====================================================

Below is an example C++ code that reads network packets from a socket on port 888.

### Prerequisites

*   C++ compiler (e.g., `g++`)
*   POSIX-compliant system (e.g., Linux, macOS)

### Code

```cpp
#include <iostream>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 888
#define BUFFER_SIZE 1024

// Function to handle errors
void handleError(const std::string& message) {
    std::cerr << "Error: " << message << std::endl;
    exit(1);
}

int main() {
    int serverSocket, clientSocket;
    struct sockaddr_in serverAddress, clientAddress;
    socklen_t clientAddressLength = sizeof(clientAddress);
    char buffer[BUFFER_SIZE];

    // Create server socket
    serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket < 0) {
        handleError("Failed to create server socket");
    }

    // Set server address
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(PORT);
    inet_pton(AF_INET, "0.0.0.0", &serverAddress.sin_addr);

    // Bind server socket to address and port
    if (bind(serverSocket, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) < 0) {
        handleError("Failed to bind server socket");
    }

    // Listen for incoming connections
    if (listen(serverSocket, 3) < 0) {
        handleError("Failed to listen for incoming connections");
    }

    std::cout << "Server listening on port " << PORT << std::endl;

    while (true) {
        // Accept incoming client connection
        clientSocket = accept(serverSocket, (struct sockaddr*)&clientAddress, &clientAddressLength);
        if (clientSocket < 0) {
            handleError("Failed to accept client connection");
        }

        std::cout << "Client connected" << std::endl;

        while (true) {
            // Read data from client socket
            int bytesRead = read(clientSocket, buffer, BUFFER_SIZE);
            if (bytesRead < 0) {
                handleError("Failed to read data from client socket");
            } else if (bytesRead == 0) {
                std::cout << "Client disconnected" << std::endl;
                break;
            }

            // Print received data
            buffer[bytesRead] = '\0';
            std::cout << "Received: " << buffer << std::endl;

            // Send response back to client (optional)
            // char* response = "Hello, client!";
            // send(clientSocket, response, strlen(response), 0);
        }

        // Close client socket
        close(clientSocket);
    }

    // Close server socket
    close(serverSocket);

    return 0;
}
```

### Compilation and Execution

Compile the code using:

```bash
g++ -o network_server network_server.cpp
```

Run the server:

```bash
./network_server
```

### Testing

You can test the server by using tools like `telnet` or `nc` (Netcat):

```bash
telnet localhost 888
```

or

```bash
nc localhost 888
```

Type messages and press Enter to send them to the server. The server will print the received messages.

**Note:** This is a basic example and does not include error handling for all possible scenarios. You may want to add additional checks and handling depending on your specific requirements.

To create a 500x500 pixel square with a rounded top-right corner in After Effects using expressions, you'll need to manipulate the path property of a shape layer. The path property can be represented as an array of points that define the shape. 

Below is an example expression that you can add to the path property of a shape layer to achieve this. This expression creates a square with sides of 500 pixels and rounds the top-right corner. The radius of the rounded corner is set to 50 pixels for demonstration, but you can adjust this value as needed.

```javascript
// Define the size of the square
var squareSize = 500;
// Define the radius of the rounded corner
var cornerRadius = 50;

// Starting point (top left)
var p0 = [0, 0];
// End point of top side (top right)
var p1 = [squareSize, 0];
// Control point for rounded corner (top right)
var cp1 = [squareSize - cornerRadius, 0];
// Control point for rounded corner (top right)
var cp2 = [squareSize, cornerRadius];
// End point of right side (bottom right)
var p2 = [squareSize, squareSize];
// End point of bottom side (bottom left)
var p3 = [0, squareSize];

// Create the path
var path = [
  p0,
  p1,
  // Bezier curve for rounded corner
  Bezier(p1, cp1, cp2, p2),
  p3,
  p0
];

// Return the path
path;
```

However, directly using `Bezier` function in such a straightforward manner might not be directly supported in After Effects expressions as it is in some other programming contexts. 

A more accurate approach for After Effects expressions would involve directly defining the points and using linear interpolation for the Bezier curve or directly creating the rounded corner points. Here's a simplified version that directly calculates and defines the points for a square with a rounded top-right corner:

```javascript
// Define the size of the square
squareSize = 500;
// Define the radius of the rounded corner
cornerRadius = 50;

// Points for the square with a rounded top-right corner
p0 = [0, 0];
p1 = [squareSize - cornerRadius, 0];
p2 = [squareSize, cornerRadius];
p3 = [squareSize, squareSize - cornerRadius];
p4 = [squareSize - cornerRadius, squareSize];
p5 = [0, squareSize];

// Create the path
path = [
  p0,
  p1,
  p2,
  p3,
  p4,
  p5,
  p0
];

// Return the path
path;
```

To apply this expression:
1. Create a new shape layer in your composition.
2. Go to the `Path` property of the shape.
3. Alt-click (Option-click on Mac) the stopwatch next to `Path` to open the expression editor.
4. Paste the expression into the expression editor.

Adjust `squareSize` and `cornerRadius` at the top of the expression to fine-tune the size of your square and the roundness of the corner.

To accomplish the task of merging two Word documents (.docx) into one using the OpenXML SDK in C#, you will need to have the OpenXML SDK installed. You can install it via NuGet Package Manager. Here is a basic example of how you could achieve this. This example assumes you have basic knowledge of C# and OpenXML.

Please note that directly extracting pages from a Word document is not straightforward because, unlike PDF files, Word documents do not inherently define pages. Pages are dynamically generated based on the content and layout when you open the document in a viewer. However, we can approximate taking the first two pages by controlling the content flow.

This example will:
1. Open the first document and extract its header, footer, and the first two paragraphs (approximating two pages).
2. Open the second document and extract its body content (excluding headers and footers) and glossary.

Then, it merges these extracted elements into a new document.

```csharp
using System;
using System.IO;
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;

namespace MergeWordDocuments
{
    class Program
    {
        static void Main(string[] args)
        {
            string sourceDoc1 = @"C:\Path\To\Document1.docx";
            string sourceDoc2 = @"C:\Path\To\Document2.docx";
            string outputDoc = @"C:\Path\To\MergedDocument.docx";

            MergeDocuments(sourceDoc1, sourceDoc2, outputDoc);
        }

        static void MergeDocuments(string sourceDoc1, string sourceDoc2, string outputDoc)
        {
            // Open the first document
            using (WordprocessingDocument doc1 = WordprocessingDocument.Open(sourceDoc1, true))
            {
                // Open the second document
                using (WordprocessingDocument doc2 = WordprocessingDocument.Open(sourceDoc2, true))
                {
                    // Create a new document
                    using (WordprocessingDocument newDoc = WordprocessingDocument.Create(outputDoc, WordprocessingDocumentType.Document))
                    {
                        // Copy styles
                        CopyStyles(doc1, newDoc);

                        // Copy headers and footers
                        CopyHeadersFooters(doc1, newDoc);

                        // Copy first two paragraphs (approx. first two pages)
                        CopyParagraphs(doc1, newDoc, 2);

                        // Copy body content from the second document
                        CopyBodyContent(doc2, newDoc);

                        // Copy glossary from the second document
                        // Glossary is usually in the /word/glossary/document.xml part
                        if (doc2.MainDocumentPart.GlossaryDocumentPart != null)
                        {
                            newDoc.MainDocumentPart.GlossaryDocumentPart = new GlossaryDocumentPart();
                            doc2.MainDocumentPart.GlossaryDocumentPart.Save(newDoc.MainDocumentPart.GlossaryDocumentPart);
                        }

                        // Save changes
                        newDoc.Save();
                    }
                }
            }
        }

        static void CopyStyles(WordprocessingDocument source, WordprocessingDocument target)
        {
            var sourceStyles = source.MainDocumentPart.StyleDefinitionsPart;
            if (sourceStyles != null)
            {
                target.MainDocumentPart.StyleDefinitionsPart = new StyleDefinitionsPart();
                sourceStyles.Clone(target.MainDocumentPart.StyleDefinitionsPart);
            }
        }

        static void CopyHeadersFooters(WordprocessingDocument source, WordprocessingDocument target)
        {
            // Headers
            foreach (var header in source.MainDocumentPart.HeaderParts)
            {
                var newHeader = new HeaderPart();
                header.Clone(newHeader);
                target.MainDocumentPart.HeaderParts.Add(newHeader);
            }

            // Footers
            foreach (var footer in source.MainDocumentPart.FooterParts)
            {
                var newFooter = new FooterPart();
                footer.Clone(newFooter);
                target.MainDocumentPart.FooterParts.Add(newFooter);
            }
        }

        static void CopyParagraphs(WordprocessingDocument source, WordprocessingDocument target, int count)
        {
            var sourceBody = source.MainDocumentPart.Document.Body;
            var targetBody = target.MainDocumentPart.Document.Body;

            int paragraphCount = 0;
            foreach (var para in sourceBody.Elements<Paragraph>())
            {
                if (paragraphCount >= count) break;
                targetBody.Append(para.Clone() as Paragraph);
                paragraphCount++;
            }
        }

        static void CopyBodyContent(WordprocessingDocument source, WordprocessingDocument target)
        {
            var sourceBody = source.MainDocumentPart.Document.Body;
            var targetBody = target.MainDocumentPart.Document.Body;

            foreach (var element in sourceBody.Elements())
            {
                if (element is Paragraph || element is Table)
                {
                    targetBody.Append(element.Clone());
                }
            }
        }
    }
}
```

This example provides a basic framework for merging documents but might require adjustments based on the complexity and structure of your source documents. Keep in mind that handling images and other media involves copying the `Relationships` parts appropriately, which is not fully covered here.

Also, note that directly working with OpenXML can be complex and error-prone. Consider using a library like Aspose.Words if you encounter too many issues or if your requirements become more complex.

