**Old-School Raycasting with GLSL**
=====================================

In this example, we'll create a simple old-school raycaster using GLSL shaders. This technique was popularized by games like Wolfenstein 3D and Doom.

**Vertex Shader**
----------------

```glsl
#version 330 core

layout (location = 0) in vec3 aPos;

uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

void main()
{
    gl_Position = projection * view * model * vec4(aPos, 1.0);
}
```

**Fragment Shader**
------------------

```glsl
#version 330 core

out vec4 FragColor;

uniform vec2 resolution;
uniform float time;
uniform int max_distance = 100;

// Simple map function for demonstration purposes
float map(vec3 p) {
    // Replace this with your own map function
    return length(p) - 5.0;
}

void main()
{
    vec2 uv = (gl_FragCoord.xy - resolution / 2.0) / resolution.y;
    vec3 ray_origin = vec3(0.0, 0.0, -5.0);
    vec3 ray_direction = normalize(vec3(uv, 1.0));

    float t = 0.0;
    for (int i = 0; i < max_distance; i++) {
        vec3 p = ray_origin + t * ray_direction;
        float d = map(p);
        if (d < 0.001) {
            // Simple lighting
            vec3 normal = normalize(vec3(
                map(p + vec3(0.01, 0.0, 0.0)) - d,
                map(p + vec3(0.0, 0.01, 0.0)) - d,
                map(p + vec3(0.0, 0.0, 0.01)) - d
            ));
            float light = max(dot(normal, vec3(1.0, 1.0, 1.0) / sqrt(3.0)), 0.0);
            FragColor = vec4(vec3(light), 1.0);
            return;
        }
        t += d;
    }

    // Background color
    FragColor = vec4(vec3(0.2), 1.0);
}
```

**Example Usage**
-----------------

To use these shaders, you'll need to set up an OpenGL context and create a full-screen quad. You can then pass the `resolution`, `time`, and `max_distance` uniforms to the shaders.

Here's a simple example using GLFW and GLM:

```cpp
#include <GLFW/glfw3.h>
#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>

int main() {
    // Initialize GLFW and create a window
    glfwInit();
    GLFWwindow* window = glfwCreateWindow(800, 600, "Raycaster", NULL, NULL);
    glfwMakeContextCurrent(window);

    // Create and compile shaders
    GLuint vertex_shader = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vertex_shader, 1, &vertex_shader_source, NULL);
    glCompileShader(vertex_shader);

    GLuint fragment_shader = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fragment_shader, 1, &fragment_shader_source, NULL);
    glCompileShader(fragment_shader);

    GLuint program = glCreateProgram();
    glAttachShader(program, vertex_shader);
    glAttachShader(program, fragment_shader);
    glLinkProgram(program);

    // Create a full-screen quad
    GLfloat quad_vertices[] = {
        -1.0f, -1.0f, 0.0f,
         1.0f, -1.0f, 0.0f,
         1.0f,  1.0f, 0.0f,
        -1.0f,  1.0f, 0.0f
    };

    GLuint quad_vao, quad_vbo;
    glGenVertexArrays(1, &quad_vao);
    glGenBuffers(1, &quad_vbo);
    glBindVertexArray(quad_vao);
    glBindBuffer(GL_ARRAY_BUFFER, quad_vbo);
    glBufferData(GL_ARRAY_BUFFER, sizeof(quad_vertices), quad_vertices, GL_STATIC_DRAW);
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 3 * sizeof(GLfloat), (GLvoid*)0);
    glEnableVertexAttribArray(0);

    while (!glfwWindowShouldClose(window)) {
        glfwPollEvents();

        // Clear screen
        glClearColor(0.2f, 0.2f, 0.2f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT);

        // Use program and set uniforms
        glUseProgram(program);
        glUniform2f(glGetUniformLocation(program, "resolution"), 800.0f, 600.0f);
        glUniform1f(glGetUniformLocation(program, "time"), (float)glfwGetTime());
        glUniform1i(glGetUniformLocation(program, "max_distance"), 100);

        // Draw quad
        glBindVertexArray(quad_vao);
        glDrawArrays(GL_QUADS, 0, 4);

        glfwSwapBuffers(window);
    }

    glfwTerminate();
    return 0;
}
```

