**server/routes/todoRoutes.js**
```javascript
const express = require('express');
const router = express.Router();
const { Pool } = require('pg');

const pool = new Pool({
    user: 'your_username',
    host: 'your_host',
    database: 'todo_app',
    password: 'your_password',
    port: 5432,
});

// Get all to-do items
router.get('/', async (req, res) => {
    try {
        const result = await pool.query('SELECT * FROM todos');
        res.json(result.rows);
    } catch (err) {
        console.error(err);
        res.status(500).json({ message: 'Error fetching to-do items' });
    }
});

// Create a new to-do item
router.post('/', async (req, res) => {
    try {
        const { title } = req.body;
        const result = await pool.query('INSERT INTO todos (title) VALUES ($1) RETURNING *', [title]);
        res.json(result.rows[0]);
    } catch (err) {
        console.error(err);
        res.status(500).json({ message: 'Error creating to-do item' });
    }
});

// Update a to-do item
router.put('/:id', async (req, res) => {
    try {
        const { id } = req.params;
        const { title, completed } = req.body;
        const result = await pool.query('UPDATE todos SET title = $1, completed = $2 WHERE id = $3 RETURNING *', [title, completed, id]);
        res.json(result.rows[0]);
    } catch (err) {
        console.error(err);
        res.status(500).json({ message: 'Error updating to-do item' });
    }
});

// Delete a to-do item
router.delete('/:id', async (req, res) => {
    try {
        const { id } = req.params;
        await pool.query('DELETE FROM todos WHERE id = $1', [id]);
        res.json({ message: 'To-do item deleted successfully' });
    } catch (err) {
        console.error(err);
        res.status(500).json({ message: 'Error deleting to-do item' });
    }
});

module.exports = router;
```

### Step 5: Set up the Client

**client/src/index.js**
