**client/src/App.js**
```javascript
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import TodoList from './components/TodoList';

function App() {
    const [todos, setTodos] = useState([]);
    const [newTodo, setNewTodo] = useState('');

    useEffect(() => {
        axios.get('http://localhost:5000/api/todos')
            .then(response => {
                setTodos(response.data);
            })
            .catch(error => {
                console.error(error);
            });
    }, []);

    const handleAddTodo = () => {
        axios.post('http://localhost:5000/api/todos', { title: newTodo })
            .then(response => {
                setTodos([...todos, response.data]);
                setNewTodo('');
            })
            .catch(error => {
                console.error(error);
            });
    };

    const handleUpdateTodo = (id, title, completed) => {
        axios.put(`http://localhost:5000/api/todos/${id}`, { title, completed })
            .then(response => {
                setTodos(todos.map(todo => todo.id === id ? response.data : todo));
            })
            .catch(error => {
                console.error(error);
            });
    };

    const handleDeleteTodo = (id) => {
        axios.delete(`http://localhost:5000/api/todos/${id}`)
            .then(() => {
                setTodos(todos.filter(todo => todo.id !== id));
            })
            .catch(error => {
                console.error(error);
            });
    };

    return (
        <div>
            <h1>To-Do List</h1>
            <input
                type="text"
                value={newTodo}
                onChange={(e) => setNewTodo(e.target.value)}
                placeholder="Add new to-do item"
            />
            <button onClick={handleAddTodo}>Add</button>
            <TodoList
                todos={todos}
                handleUpdateTodo={handleUpdateTodo}
                handleDeleteTodo={handleDeleteTodo}
            />
        </div>
    );
}

export default App;
```

**client/src/components/TodoList.js**
