import React from 'react';
import TodoItem from './TodoItem';

function TodoList({ todos, handleUpdateTodo, handleDeleteTodo }) {
    return (
        <ul>
            {todos.map(todo => (
                <TodoItem
                    key={todo.id}
                    todo={todo}
                    handleUpdateTodo={handleUpdateTodo}
