**MNIST Neural Network using Vitis HLS**
======================================

In this example, we will implement a basic neural network for handwritten digit recognition using the MNIST dataset. The network consists of one input layer, two hidden layers, and one output layer.

**Network Architecture**
------------------------

* Input Layer: 784 neurons (28x28 images)
* Hidden Layer 1: 256 neurons (ReLU activation)
* Hidden Layer 2: 128 neurons (ReLU activation)
* Output Layer: 10 neurons (softmax activation)

**Vitis HLS Code**
------------------

```cpp
#include "ap_int.h"
#include "ap_fixed.h"

// Define the network parameters
const int IMG_SIZE = 784;
const int HIDDEN1_SIZE = 256;
const int HIDDEN2_SIZE = 128;
const int OUTPUT_SIZE = 10;

// Define the weights and biases for the network
const int weights1_rows = IMG_SIZE;
const int weights1_cols = HIDDEN1_SIZE;
const int weights2_rows = HIDDEN1_SIZE;
const int weights2_cols = HIDDEN2_SIZE;
const int weights3_rows = HIDDEN2_SIZE;
const int weights3_cols = OUTPUT_SIZE;

ap_fixed<16, 8> weights1[weights1_rows][weights1_cols];
ap_fixed<16, 8> weights2[weights2_rows][weights2_cols];
ap_fixed<16, 8> weights3[weights3_rows][weights3_cols];

ap_fixed<16, 8> bias1[HIDDEN1_SIZE];
ap_fixed<16, 8> bias2[HIDDEN2_SIZE];
ap_fixed<16, 8> bias3[OUTPUT_SIZE];

// Define the activation functions
ap_fixed<16, 8> relu(ap_fixed<16, 8> x) {
    if (x < 0) {
        return 0;
    } else {
        return x;
    }
}

ap_fixed<16, 8> softmax(ap_fixed<16, 8> x[OUTPUT_SIZE]) {
    ap_fixed<16, 8> max = x[0];
    for (int i = 1; i < OUTPUT_SIZE; i++) {
        if (x[i] > max) {
            max = x[i];
        }
    }

    ap_fixed<16, 8> sum = 0;
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        sum += exp(x[i] - max);
    }

    for (int i = 0; i < OUTPUT_SIZE; i++) {
        x[i] = exp(x[i] - max) / sum;
    }

    return x[0];
}

// Define the neural network function
void mnist_neural_network(ap_fixed<16, 8> img[IMG_SIZE], ap_fixed<16, 8> output[OUTPUT_SIZE]) {
    // Layer 1
    ap_fixed<16, 8> hidden1[HIDDEN1_SIZE];
    for (int i = 0; i < HIDDEN1_SIZE; i++) {
        hidden1[i] = 0;
        for (int j = 0; j < IMG_SIZE; j++) {
            hidden1[i] += img[j] * weights1[j][i];
        }
        hidden1[i] += bias1[i];
        hidden1[i] = relu(hidden1[i]);
    }

    // Layer 2
    ap_fixed<16, 8> hidden2[HIDDEN2_SIZE];
    for (int i = 0; i < HIDDEN2_SIZE; i++) {
        hidden2[i] = 0;
        for (int j = 0; j < HIDDEN1_SIZE; j++) {
            hidden2[i] += hidden1[j] * weights2[j][i];
        }
        hidden2[i] += bias2[i];
        hidden2[i] = relu(hidden2[i]);
    }

    // Layer 3
    ap_fixed<16, 8> out[OUTPUT_SIZE];
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        out[i] = 0;
        for (int j = 0; j < HIDDEN2_SIZE; j++) {
            out[i] += hidden2[j] * weights3[j][i];
        }
        out[i] += bias3[i];
    }

    // Softmax activation
    softmax(out);

    // Output
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output[i] = out[i];
    }
}
```

**HLS Synthesis**
------------------

To synthesize this code using Vitis HLS, create a new HLS project and add the above code to a file named `mnist_neural_network.cpp`. Then, create a `mnist_neural_network.h` file with the following contents:
