    class Program
    {
        static void Main(string[] args)
        {
            using (var client = new MyServiceClient())
            {
                string data = client.GetData();
                Console.WriteLine(data);
            }
        }
    }
}
```

Note that the actual code will vary depending on the contents of your WSDL file and the services it defines.

