        <input type="number" id="width" value="100">
        <label for="height">Height:</label>
        <input type="number" id="height" value="100">
        <button id="selectSprite">Select Sprite</button>
    </div>

    <script src="spriteEditor.js"></script>
</body>
</html>
```

### JavaScript (`spriteEditor.js`)

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const imageLoader = document.getElementById('imageLoader');
    const imageCanvas = document.getElementById('imageCanvas');
    const ctxImage = imageCanvas.getContext('2d');
    const spriteCanvas = document.getElementById('spriteCanvas');
    const ctxSprite = spriteCanvas.getContext('2d');
    let currentImage;

    imageLoader.addEventListener('change', (e) => {
        const file = e.target.files[0];
        const reader = new FileReader();
        reader.onload = (event) => {
            const image = new Image();
            image.onload = () => {
                currentImage = image;
                imageCanvas.width = image.width;
                imageCanvas.height = image.height;
                ctxImage.drawImage(image, 0, 0);
            };
            image.src = event.target.result;
        };
        reader.readAsDataURL(file);
    });

    document.getElementById('selectSprite').addEventListener('click', () => {
        if (!currentImage) {
            alert('Please load an image first.');
            return;
        }

        const x = parseInt(document.getElementById('x').value);
        const y = parseInt(document.getElementById('y').value);
        const width = parseInt(document.getElementById('width').value);
        const height = parseInt(document.getElementById('height').value);

        ctxSprite.clearRect(0, 0, spriteCanvas.width, spriteCanvas.height);
        ctxSprite.drawImage(currentImage, x, y, width, height, 0, 0, spriteCanvas.width, spriteCanvas.height);
    });
});
```

### Explanation

1. **Loading an Image**: The user can select an image file using an `<input type="file">`. The image is then drawn onto an `<canvas>` element.
2. **Selecting a Sprite**: The user inputs coordinates (`x`, `y`) and dimensions (`width`, `height`) to select a portion of the loaded image.
3. **Displaying the Sprite**: Upon clicking the "Select Sprite" button, the specified portion of the image is drawn onto another `<canvas>` element, effectively extracting and displaying the sprite.

