**Connect-4 Game in Python**
================================

### Game Overview

Connect-4 is a two-player board game where players take turns dropping colored discs into a vertical grid. The first player to get four discs in a row (horizontally, vertically, or diagonally) wins the game.

### Code

```python
import numpy as np

class Connect4:
    def __init__(self):
        self.rows = 6
        self.cols = 7
        self.board = np.zeros((self.rows, self.cols))
        self.player_turn = 1

    def print_board(self):
        print("\nCurrent Board:")
        for row in self.board:
            print(" ".join(["X" if cell == 1 else "O" if cell == 2 else "." for cell in row]))
        print(" ".join([str(i) for i in range(1, self.cols + 1)]))

    def is_valid_move(self, col):
        return self.board[0, col] == 0

    def make_move(self, col):
        for row in range(self.rows - 1, -1, -1):
            if self.board[row, col] == 0:
                self.board[row, col] = self.player_turn
                return

    def check_win(self):
        # Check horizontal locations for win
        for row in range(self.rows):
            for col in range(self.cols - 3):
                if self.board[row, col] != 0 and self.board[row, col] == self.board[row, col + 1] == self.board[row, col + 2] == self.board[row, col + 3]:
                    return True

        # Check vertical locations for win
        for col in range(self.cols):
            for row in range(self.rows - 3):
                if self.board[row, col] != 0 and self.board[row, col] == self.board[row + 1, col] == self.board[row + 2, col] == self.board[row + 3, col]:
                    return True

        # Check positively sloped diagonals
        for row in range(self.rows - 3):
            for col in range(self.cols - 3):
                if self.board[row, col] != 0 and self.board[row, col] == self.board[row + 1, col + 1] == self.board[row + 2, col + 2] == self.board[row + 3, col + 3]:
                    return True

        # Check negatively sloped diagonals
        for row in range(3, self.rows):
            for col in range(self.cols - 3):
                if self.board[row, col] != 0 and self.board[row, col] == self.board[row - 1, col + 1] == self.board[row - 2, col + 2] == self.board[row - 3, col + 3]:
                    return True

        return False

